N = 26


def objective(vars_flat):
    radii = vars_flat[2::3]
    return -np.sum(radii)


def constraint_function(vars_flat):
    vals = []
    for i in range(N):
        x = vars_flat[3 * i]
        y = vars_flat[3 * i + 1]
        r = vars_flat[3 * i + 2]
        vals.append(x - r)
        vals.append(1.0 - x - r)
        vals.append(y - r)
        vals.append(1.0 - y - r)
        vals.append(r)
    for i in range(N):
        for j in range(i + 1, N):
            dx = vars_flat[3 * i] - vars_flat[3 * j]
            dy = vars_flat[3 * i + 1] - vars_flat[3 * j + 1]
            ri = vars_flat[3 * i + 2]
            rj = vars_flat[3 * j + 2]
            vals.append(dx * dx + dy * dy - (ri + rj) * (ri + rj))
    return np.array(vals)


def constraint_wrapper(vars_flat):
    return constraint_function(vars_flat)


def make_hex_grid():
    rows = [5, 4, 5, 4, 5, 3]
    r_init = 0.04
    centers = []
