def post_process(centers, radii):
    c = centers.copy()
    r = radii.copy()
    n = len(c)

    # Clamp to square
    for i in range(n):
        x, y = c[i]
        mr = min(x, 1.0 - x, y, 1.0 - y, r[i])
        r[i] = max(0.0, mr)

    # Resolve overlaps iteratively
    for _ in range(500):
        changed = False
        for i in range(n):
            if r[i] <= 0:
                continue
            for j in range(i + 1, n):
                if r[j] <= 0:
                    continue
                dx = c[i, 0] - c[j, 0]
                dy = c[i, 1] - c[j, 1]
                d = np.sqrt(dx * dx + dy * dy)
                md = r[i] + r[j]
                if d < md - 1e-12:
                    ov = md - d
                    # Reduce proportionally to current radius
                    total = r[i] + r[j]
                    if total > 0:
                        r[i] -= ov * (r[i] / total) * 0.5
                        r[j] -= ov * (r[j] / total) * 0.5
                    else:
                        r[i] -= ov * 0.5
                        r[j] -= ov * 0.5
                    r[i] = max(0.0, r[i])
                    r[j] = max(0.0, r[j])
                    changed = True
        if not changed:
            break

    return c, r


def try_optimization(centers, radii):
